from typing import List, Union

def below_zero(operations: Union[List[int], str]) -> Union[bool, List[bool]]:
    if isinstance(operations, list):
        balance = 0
        for op in operations:
            balance += op
            if balance < 0:
                return True
        return False
    elif isinstance(operations, str):
        balance = 0
        result = []
        for ch in operations:
            balance += int(ch)
            result.append(balance < 0)
        return result


