from typing import List

def parse_music(music_string: str) -> List[int]:
    """
    Parses a string of musical notes in a special ASCII format into a list of beat durations.
    Returns an empty list if the input is empty or only whitespace.

    Legend:
    'o'  - whole note, lasts 4 beats
    'o|' - half note, lasts 2 beats
    '.|' - quarter note, lasts 1 beat

    Notes are separated by spaces.

    According to the authoritative user specification:
    - Return just the list of beat integers for any non-empty input.
    - Return an empty list for empty input.
    """
    if not music_string.strip():
        return []

    beats_map = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    tokens = music_string.split()
    beats = [beats_map[token] for token in tokens if token in beats_map]
    return beats


