from typing import List, Any, Tuple

def filter_integers(values: List[Any], format: str) -> Tuple[List[int], str]:
    """ 
    Filter given list of any Python values only for integers (excluding bools) and return them as a list.
    Also return a space-separated string of the non-integer values (including bools), preserving the original order.
    The output tuple is (list_of_integers, string_of_non_integers).
    The 'format' parameter is accepted but does not affect output.

    Note:
    - Input can be any iterable of values.
    - Boolean values are excluded from the integer list and treated as non-integers.
    - Non-integer values are converted to strings and joined with spaces in the output string.

    Examples:
    >>> filter_integers(['a', 3.14, 5], 'integer')
    ([5], 'a 3.14')
    >>> filter_integers([1, 2, 3, 'abc', {}, []], 'string')
    ([1, 2, 3], 'abc {} []')
    >>> filter_integers([True, False, 1, 2, 'a'], 'string')
    ([1, 2], 'True False a')
    """
    integers = []
    non_integers = []
    for v in values:
        if isinstance(v, int) and not isinstance(v, bool):
            integers.append(v)
        else:
            non_integers.append(str(v))
    return integers, ' '.join(non_integers)


