def triples_sum_to_zero(l: list):
    l = [int(x) for x in l]
    n = len(l)
    l.sort()
    for i in range(n - 2):
        a = l[i]
        left, right = i + 1, n - 1
        while left < right:
            s = a + l[left] + l[right]
            if s == 0:
                return 'True'
            elif s < 0:
                left += 1
            else:
                right -= 1
    return 'False'


