def monotonic(l):
    if not l:
        # Empty list or string: True and sum 0 or "" accordingly
        return True if isinstance(l, list) else (True, "")
    if isinstance(l, list):
        # For lists: return only boolean, True if strictly monotonic (increasing or decreasing) without duplicates
        # Check duplicates
        if len(set(l)) != len(l):
            return False
        # Strictly increasing check
        inc = all(x < y for x, y in zip(l, l[1:]))
        # Strictly decreasing check
        dec = all(x > y for x, y in zip(l, l[1:]))
        return inc or dec
    elif isinstance(l, str):
        # For strings: return False if duplicates or not strictly monotonic (alphabetically increasing or decreasing),
        # else return (True, string)
        if len(set(l)) != len(l):
            return False
        inc = all(x < y for x, y in zip(l, l[1:]))
        dec = all(x > y for x, y in zip(l, l[1:]))
        if inc or dec:
            return True, l
        else:
            return False
    else:
        # If input type is neither list nor str, follow natural behavior: return False
        return False


