from collections import Counter

def search(lst):
    if not lst:
        return -1

    # Check if list contains strings only
    if all(isinstance(x, str) for x in lst):
        return max(lst)

    # Otherwise, assume integers only (positive integers, possibly zero)
    # Count frequencies
    freq = Counter(lst)

    # Find all integers i where freq[i] >= i and i > 0
    candidates = [i for i in freq if isinstance(i, int) and i > 0 and freq[i] >= i]

    if not candidates:
        return -1

    return max(candidates)


