def total_match(lst1, lst2):
    is_str_1 = any(isinstance(x, str) for x in lst1)
    is_str_2 = any(isinstance(x, str) for x in lst2)

    if is_str_1 or is_str_2:
        # Convert all elements to strings in each list and sum lengths
        sum_len_1 = sum(len(str(x)) for x in lst1)
        sum_len_2 = sum(len(str(x)) for x in lst2)
        if sum_len_1 <= sum_len_2:
            return lst1
        else:
            return lst2
    else:
        # Both lists contain only integers
        def digits_count(n):
            return len(str(abs(n)))
        sum_digits_1 = sum(digits_count(x) for x in lst1)
        sum_digits_2 = sum(digits_count(x) for x in lst2)
        if sum_digits_1 <= sum_digits_2:
            return ' '.join(str(x) for x in lst1)
        else:
            return ' '.join(str(x) for x in lst2)


