def prime_length(string):
    length = len(string)
    if length < 2:
        return 0
    if length == 2:
        return 1
    if length % 2 == 0:
        return 0
    for i in range(3, int(length**0.5) + 1, 2):
        if length % i == 0:
            return 0
    return 1


