def anti_shuffle(s: str) -> str:
    res = []
    word = []
    for ch in s:
        if ch == ' ':
            if word:
                res.append(''.join(sorted(word)))
                word = []
            res.append(ch)
        else:
            word.append(ch)
    if word:
        res.append(''.join(sorted(word)))
    return ''.join(res)


