def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    sorted_arr = sorted(arr)

    # Try all possible right shifts: from 0 to n-1
    for shifts in range(n):
        # Right shift by 'shifts': last 'shifts' elements come to front
        shifted = arr[-shifts:] + arr[:-shifts]
        if shifted == sorted_arr:
            return True
    return False


