def max_fill(grid, capacity):
    import math
    # Sum water units per well (row) without sorting
    water_per_well = list(map(sum, grid))
    # Compute bucket lowers needed per well using ceiling division
    lowers_per_well = list(map(lambda w: math.ceil(w / capacity), water_per_well))
    # Sum all lowers and return as string
    return str(sum(lowers_per_well))


