    This function must work for both strings and integer inputs but the task is to work with strings only.
    Examples:
    retrieve_words("Mary had a little lamb", 4) ==> 1
    retrieve_words("Mary had a little lamb", 3) ==> 2
    retrieve_words("simple white space", 2) ==> 0
    retrieve_words("Hello world", 4) ==> 1
    retrieve_words("Uncle sam", 3) ==> 1
    """


def select_words(s: str, n: int) -> list[str]:
    if not s or ' ' not in s:
        return []
    vowels = set("aeiouAEIOU")
    result = []
    for word in s.split():
        consonant_count = sum(1 for ch in word if ch.isalpha() and ch not in vowels)
        if consonant_count == n:
            result.append(word)
    return result


