def digits(n, s=None):
    # Determine the string to extract digits from
    source = str(s) if s is not None else str(n)

    odd_product = 1
    even_product = 1
    odd_found = False
    even_found = False

    for ch in source:
        if ch.isdigit():
            d = int(ch)
            if d % 2 == 1:
                odd_product *= d
                odd_found = True
            else:
                even_product *= d
                even_found = True

    # If no odd digits, odd product is '0' (str)
    if not odd_found:
        odd_product = '0'
    else:
        odd_product = str(odd_product)

    # If no even digits, even product is 0 (int)
    if not even_found:
        even_product = 0

    # Return odd product as str if n is str, else even product as int if n is int
    if isinstance(n, str):
        return odd_product
    else:
        return even_product


