def sum_squares(lst):
    total = 0
    for x in lst:
        int_x = int(x)
        # Determine ceiling without using ceil or round
        if x > int_x:
            ceil_x = int_x + 1
        else:
            ceil_x = int_x
        total += ceil_x * ceil_x
    return total


