def order_by_points(nums):
    if not nums:
        return []

    def digit_sum(x):
        s = str(x)
        digits = [int(ch) for ch in s if ch.isdigit()]
        return sum(digits)

    return [x for _, x in sorted(enumerate(nums), key=lambda iv: (digit_sum(iv[1]), iv[0]))]


