from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Parses the input string containing one or more groups of nested parentheses separated by spaces.
    Returns a list of integers representing the maximum nesting depth of parentheses for each group.

    Only space characters (ASCII 0x20) separate groups. Other non-parenthesis characters do not split groups.
    Each group's maximum nesting depth is computed based solely on '(' and ')' characters in that group.
    """
    groups = paren_string.split(' ')
    depths = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths


