def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits left or right by shift
    and return the result as a string.
    A positive shift rotates the digits to the right,
    a negative shift rotates the digits to the left,
    preserving the sign if negative.
    """
    sign = '-' if x < 0 else ''
    digits = str(abs(x))
    n = len(digits)
    if n == 0:
        return sign
    shift = shift % n  # Normalize shift to be within the length of digits
    if shift == 0:
        return sign + digits
    # Positive shift: rotate right by shift
    # Negative shift: rotate left by abs(shift) == rotate right by n - abs(shift)
    # Since shift is already modulo n and positive or zero, rotate right by shift.
    shifted = digits[-shift:] + digits[:-shift]
    return sign + shifted


