import math

def max_fill(grid, capacity):
    """
    Given a grid of wells (list of list of 0/1 integers) and a bucket capacity,
    compute the total number of buckets needed to extract all water units,
    counting buckets per well by dividing the sum of 1s by capacity and rounding up,
    then summing these counts across all wells.
    """
    total_buckets = 0
    for well in grid:
        water_units = sum(well)
        buckets_needed = math.ceil(water_units / capacity) if capacity > 0 else 0
        total_buckets += buckets_needed
    return total_buckets


