def sort_even(l: list):
    if len(l) <= 1:
        return l
    even_indices = list(range(0, len(l), 2))
    even_values = [l[i] for i in even_indices]
    even_values.sort()
    result = l[:]
    for i, val in zip(even_indices, even_values):
        result[i] = val
    return result


