def anti_shuffle(s):
    """
    For each space-separated word in the input string s,
    return a string where each word's characters are fully sorted by ASCII value.
    The order of words and spaces is preserved.
    """
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)


