def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        # For negative numbers, first digit is negated
        if n < 0:
            first_digit = -int(s[0])
            rest = sum(int(d) for d in s[1:])
            return first_digit + rest
        else:
            return sum(int(d) for d in s)

    return [num for _, num in sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0]))]


