from typing import List, TypeVar

T = TypeVar('T')

def monotonic(l: List[T]) -> bool:
    if not l:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            non_decreasing = False
        if l[i] > l[i - 1]:
            non_increasing = False
    return non_decreasing or non_increasing


