def sum_to_n(n: int) -> int:
    """sum_to_n sums numbers from 1 to n.

    For zero or negative inputs, returns 0.

    >>> sum_to_n(30)
    465
    >>> sum_to_n(100)
    5050
    >>> sum_to_n(5)
    15
    >>> sum_to_n(10)
    55
    >>> sum_to_n(1)
    1
    >>> sum_to_n(0)
    0
    >>> sum_to_n(-10)
    0
    """
    if n <= 0:
        return 0
    return n * (n + 1) // 2


