def smallest_change(arr):
    """
    Given an array arr of integers, find the minimum number of elements that
    need to be changed to make the array palindromic. A palindromic array is an array that
    reads the same backwards and forwards. In one change, you can change one element to any other element.

    The function counts the number of mismatched pairs and assumes each mismatched pair requires exactly one change.

    Args:
        arr (list of int): The input array.

    Returns:
        int: The minimum number of single-element changes needed to make the array palindromic.
    """
    n = len(arr)
    changes = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes


