def anti_shuffle(s: str) -> str:
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            # Preserve all consecutive space characters exactly as is
            start = i
            while i < n and s[i] == ' ':
                i += 1
            result.append(s[start:i])
        else:
            # Collect a chunk until the next space or end of string
            start = i
            while i < n and s[i] != ' ':
                i += 1
            chunk = s[start:i]
            # Sort characters of the chunk by ASCII ascending
            sorted_chunk = ''.join(sorted(chunk))
            result.append(sorted_chunk)
    return ''.join(result)


