def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0:
            # first digit counted negatively
            digits[0] = -digits[0]
        return sum(digits)
    return [x for _, x in sorted(enumerate(nums), key=lambda ix: (digit_sum(ix[1]), ix[0]))]


