def candidate(l: list):
    """Return True if list elements are monotonic.
  >>> candidate([1, 2, 4, 20])
  False
  >>> candidate([1, 20, 4, 10])
  True
  >>> candidate([4, 1, 0, -10])
  False
  """


def monotonic(l: list) -> bool:
    if len(l) <= 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(l)):
        if l[i] < l[i-1]:
            non_decreasing = False
        if l[i] > l[i-1]:
            non_increasing = False
        if not non_decreasing and not non_increasing:
            return False
    return True


