def candidate(nums):
    """
  Note: if there are several items with similar sum of their digits,
  order them based on their index in original list.

  For example:
  >>> candidate([1, 11, -1, -11, -12]) == [1, 11, -1, -12, -11]
  >>> candidate([]) == []
  """


def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit is negative
            total = -int(s[1])
            for ch in s[2:]:
                total += int(ch)
            return total
        else:
            return sum(int(ch) for ch in s)
    return sorted(nums, key=lambda x: digit_sum(x))


