def triples_sum_to_zero(lst: list) -> bool:
    """
    Returns True if there exist three distinct elements in lst whose sum is zero, False otherwise.
    """
    n = len(lst)
    lst.sort()
    for i in range(n - 2):
        # Avoid duplicates for i
        if i > 0 and lst[i] == lst[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            s = lst[i] + lst[left] + lst[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False


