def circular_shift(x, shift):
    s = str(abs(x))
    n = len(s)
    if abs(shift) > n:
        return s[::-1]
    shift = shift % n
    # According to the authoritative clarification:
    # positive shift = shift digits to the left
    # negative shift = shift digits to the right
    # We have adjusted shift modulo n above, so shift is in [0, n-1].
    # Left shift by 'shift' means: s[shift:] + s[:shift]
    return s[shift:] + s[:shift]


