def anti_shuffle(s):
    def reorder_word(word):
        # Extract alphabetic characters and sort them ascending ASCII
        letters = sorted(c for c in word if c.isalpha())
        result = []
        letter_idx = 0
        for c in word:
            if c.isalpha():
                result.append(letters[letter_idx])
                letter_idx += 1
            else:
                result.append(c)
        return ''.join(result)

    # Split by spaces preserving spaces to rejoin exactly as in input
    parts = s.split(' ')
    reordered_parts = [reorder_word(part) for part in parts]
    return ' '.join(reordered_parts)


