def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    for k in range(n):
        rotated = arr[-k:] + arr[:-k]
        if all(rotated[i] <= rotated[i+1] for i in range(n - 1)):
            return True
    return False


