def select_words(s, n):
    vowels = set("aeiouAEIOU")
    if not s:
        return []

    # Extract all consonants from s in order
    consonants = [c for c in s if c.isalpha() and c not in vowels]

    # If there are fewer than n consonants, no words can match
    if len(consonants) < n:
        return []

    nth_consonant = consonants[n - 1].lower()

    result = []
    for word in s.split():
        # Find the first consonant in the word (case-insensitive)
        first_consonant = next((c.lower() for c in word if c.isalpha() and c not in vowels), None)
        if first_consonant is not None and first_consonant == nth_consonant:
            result.append(word)

    return result


