def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        total = 0
        # Handle sign for first digit if negative
        if s[0] == '-':
            total += -int(s[1])
            digits = s[2:]
        else:
            total += int(s[0])
            digits = s[1:]
        for d in digits:
            total += int(d)
        return total

    return sorted(nums, key=digit_sum)


