def digitSum(n: int) -> int:
    s = str(n)
    if s[0] == '-':
        # Negative number: subtract first digit after minus, add the rest
        first_digit = int(s[1])
        rest_sum = sum(int(d) for d in s[2:])
        return -first_digit + rest_sum
    else:
        # Non-negative number: sum all digits
        return sum(int(d) for d in s)


