def will_it_fly(q, w):
    if not q.ok:
        return False
    if q.sum > w:
        return False
    # Check if q is a sequence of numeric elements
    # If q has multiple numeric elements, q itself must be a palindrome
    # Determine if q is a sequence of numeric elements:
    # We'll consider that if q has __len__ and __getitem__ attributes, treat it as a sequence
    # and check if all elements are numeric (int or float).
    try:
        length = len(q)
        elems = [q[i] for i in range(length)]
        if all(isinstance(x, (int, float)) for x in elems):
            # Check palindrome
            if elems != elems[::-1]:
                return False
    except Exception:
        # If q is not a sequence, no palindrome check needed
        pass
    return True


