def anti_shuffle(data: str) -> str:
    # Split the input by spaces, preserving spaces exactly as is by splitting on spaces
    # but we must preserve spaces as in the original string.
    # Instead of splitting, iterate and rebuild preserving spaces.
    result = []
    piece = []
    for ch in data:
        if ch == ' ':
            # When hitting a space, sort the piece collected so far and append
            if piece:
                result.append(''.join(sorted(piece)))
                piece = []
            result.append(' ')  # preserve space as is
        else:
            piece.append(ch)
    # Append last piece if any
    if piece:
        result.append(''.join(sorted(piece)))
    return ''.join(result)


