def select_words(s: str, n: int) -> list[str]:
    vowels = set("aeiouAEIOU")
    result = []
    for word in s.split():
        non_vowel_count = sum(1 for ch in word if ch.isalpha() and ch not in vowels)
        if non_vowel_count == n:
            result.append(word)
    return result


