from typing import Iterable, Union

def sum_squares(collection: Iterable[Union[int, float]]) -> Union[int, float]:
    total = 0
    for i, x in enumerate(collection):
        if i % 3 == 0:
            total += x ** 2
        elif i % 4 == 0:
            # i % 3 != 0 guaranteed here
            total += x ** 3
        else:
            total += x
    return total


