from typing import Iterable

def mean_absolute_deviation(items: Iterable[float]) -> float:
    items_list = list(items)
    if not items_list:
        return 0.0
    mean = sum(items_list) / len(items_list)
    return sum(abs(x - mean) for x in items_list) / len(items_list)


