def scan_values(limit):
    """Provide a count of how often the character 7 shows up in numbers below the limit that are divisible by 11 or 13.
    >>> scan_values(50)
    0
    >>> scan_values(78)
    2
    >>> scan_values(79)
    3
    """


def fizz_buzz(limit: int) -> int:
    count = 0
    for n in range(limit):
        if n % 11 == 0 or n % 13 == 0:
            count += str(n).count('7')
    return count


