def inspect_items(items):
    """
    inspect_items accepts a collection of values.
    it should indicate True if there are three separate entries in the collection that
    add up to zero, and False otherwise.

    >>> inspect_items([1, 3, 5, 0])
    False
    >>> inspect_items([1, 3, -2, 1])
    True
    >>> inspect_items([1, 2, 3, 7])
    False
    >>> inspect_items([2, 4, -5, 3, 9, 7])
    True
    >>> inspect_items([1])
    False
    """


def triples_sum_to_zero(items):
    items = list(items)
    items.sort()
    n = len(items)
    for i in range(n - 2):
        # To avoid checking duplicates for i, uncomment next two lines if desired:
        # if i > 0 and items[i] == items[i - 1]:
        #     continue
        left, right = i + 1, n - 1
        while left < right:
            total = items[i] + items[left] + items[right]
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False


