def smallest_change(items):
    """
    Given a sequence of values, returns the count of mismatched pairs 
    that need to be altered to make the sequence palindromic.
    Each modification can fix one mismatched pair as a single change.

    Args:
        items (sequence): Sequence of values.

    Returns:
        int: Number of mismatched pairs between the sequence and its reverse.
    """
    n = len(items)
    count = 0
    for i in range(n // 2):
        if items[i] != items[n - 1 - i]:
            count += 1
    return count


