def check_size(item):
    """Create a small routine that accepts some text and indicates a truthy result when its overall size seems to be a prime-like count and a falsy one otherwise
    Examples
    check_size('Hello') == True
    check_size('abcdcba') == True
    check_size('kittens') == True
    check_size('orange') == False
    """


def prime_length(item) -> bool:
    n = len(item)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True


