def tally_caps(src):
    """
    Given some text input src, determine how many vowel letters presented in uppercase occur at even positions.

    For example:
    tally_caps('aBCdEf') returns 1
    tally_caps('abcdefg') returns 0
    tally_caps('dBBE') returns 0
    """


def count_upper(src: str) -> int:
    vowels = {'A', 'E', 'I', 'O', 'U'}
    count = 0
    for i, ch in enumerate(src):
