def items(val):
    """Given a positive number val, return an overall multiplicative result of the odd parts.
    Produce 0 if none of the figures are odd.
    For example:
    items(1)  == 1
    items(4)  == 0
    items(235) == 15
    """


def digits(val: int) -> int:
    product = 1
    found_odd = False
    while val > 0:
        d = val % 10
        if d % 2 == 1:
            product *= d
            found_odd = True
        val //= 10
    return product if found_odd else 0


