def handle(seq):
    """You are given some text input seq.
    if any character appears to be a letter, change its case from lower to upper or vise versa,
    otherwise leave it as it is.
    If the input contains no such characters, reverse the whole input.
    The function should return the resulting text.
    Examples
    handle("1234") = "4321"
    handle("ab") = "AB"
    handle("#a@C") = "#A@c"
    """


def solve(seq):
    if any(c.isalpha() for c in seq):
        return ''.join(c.swapcase() if c.isalpha() else c for c in seq)
    else:
        return seq[::-1]


