from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input is a string containing multiple groups of nested parentheses separated by spaces.
    For each group, return the maximum depth of nested parentheses.

    E.g. '(()()) ((())) () ((())()())' returns [2, 3, 1, 3].
    """
    result = []
    groups = paren_string.split()
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
        result.append(max_depth)
    return result


