def monotonic(l: list) -> bool:
    if not l:
        return True
    nondecreasing = True
    nonincreasing = True
    for i in range(len(l) - 1):
        if l[i] > l[i + 1]:
            nondecreasing = False
        if l[i] < l[i + 1]:
            nonincreasing = False
    return nondecreasing or nonincreasing


