def circular_shift(x, shift):
    s = str(abs(x))
    n = len(s)
    if shift > n:
        result = s[::-1]
    else:
        if n == 0:
            result = s
        else:
            k = shift % n if n else 0
            if k == 0:
                result = s
            else:
                result = s[-k:] + s[:-k]
    return ('-' if x < 0 else '') + result


