def smallest_change(arr):
    """
    Given an array arr of integers, find the minimum number of elements that
    need to be changed to make the array palindromic. A palindromic array is an array that
    is read the same backwards and forwards. In one change, you can change one element to any other element.

    The minimum number of element changes counts each mismatched pair as exactly one change,
    and the middle element in an odd-length array does not require a change if it already matches itself.

    Args:
        arr (list[int]): List of integers.

    Returns:
        int: Minimum number of element changes to make arr palindromic.
    """
    n = len(arr)
    changes = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes


