def move_one_ball(arr):
    """
    Determine if the array can be made sorted in non-decreasing order by some number
    of right shifts.

    Right shift means moving the last element to the front.

    Args:
        arr (list of int): The input array with unique elements.

    Returns:
        bool: True if it is possible to obtain a sorted (non-decreasing) array by 
        performing right shifts any number of times, False otherwise.

    If the array is empty, return True.
    """
    if not arr:
        return True

    n = len(arr)

    # Count how many places where arr[i] > arr[i+1]
    # There should be at most one such place for the array to be a rotated sorted array.
    count_breaks = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            count_breaks += 1
            if count_breaks > 1:
                return False

    # Also check the boundary between last and first element
    if arr[-1] > arr[0]:
        # if there was already one break, this is second break
        if count_breaks == 1:
            return False
        # if no breaks inside, this is zero or one break case, still okay

    # If zero or one break, then it can be rotated to sorted form
    return True


