def max_fill(grid, capacity):
    import math
    total_lowerings = 0
    for well in grid:
        water_units = sum(well)
        # Number of bucket lowers needed for this well
        lowers = math.ceil(water_units / capacity)
        total_lowerings += lowers
    return total_lowerings


