def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # Negative number: first digit after '-' is negative, rest positive
            total = -int(s[1])
            for ch in s[2:]:
                total += int(ch)
            return total
        else:
            # Positive number: sum of digits
            return sum(int(ch) for ch in s)
    return [x for _, x in sorted(enumerate(nums), key=lambda ix: (digit_sum(ix[1]), ix[0]))]


