from collections import Counter

def search(lst):
    # Filter to keep only positive integers
    positive_lst = [x for x in lst if x > 0]
    freq = Counter(positive_lst)
    # Find all integers where frequency >= integer value
    candidates = [num for num, count in freq.items() if count >= num]
    return max(candidates) if candidates else -1


