def smallest_change(arr):
    """
    Given an array arr of integers, find the minimum number of element changes needed
    to make the array palindromic. Count each mismatched pair as requiring exactly one 
    element change, without considering shared element changes across pairs.

    For example:
    smallest_change([1, 2, 3, 4, 5, 2, 1]) == 1
    """
    n = len(arr)
    count = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count


