def anti_shuffle(s):
    """
    Given a string s, returns a string where each word's characters are sorted by ASCII value,
    including any trailing punctuation marks (considered part of the word), so punctuation can
    move before letters if their ASCII value is smaller.

    Words are sequences separated by spaces; spaces are preserved in their original positions.

    Examples:
    anti_shuffle('Hi') -> 'Hi'
    anti_shuffle('hello') -> 'ehllo'
    anti_shuffle('Hello World!!!') -> 'Hello !!!Wdlor'
    """
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            result.append(' ')
            i += 1
            continue

        # Extract a word (sequence of non-space characters)
        start = i
        while i < n and s[i] != ' ':
            i += 1
        word = s[start:i]

        # Sort all characters of the word by ASCII value
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)

    return ''.join(result)


