def count_upper(s):
    """
    Given a string s, count the number of uppercase vowels.

    Counts only ASCII uppercase vowels: A, E, I, O, U.
    Returns 0 for empty strings or strings with no uppercase vowels.
    Ignores accented or non-ASCII characters.
    """
    vowels = {'A', 'E', 'I', 'O', 'U'}
    return sum(1 for char in s if char in vowels)


