def order_by_points(nums):
    def digit_sum_key(n):
        s = str(abs(n))
        digits = [int(d) for d in s]
        if n < 0:
            # negate only the first digit
            digits[0] = -digits[0]
        return sum(digits)
    return sorted(nums, key=digit_sum_key)


