from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    For each space-separated group of parentheses in the input string,
    returns an integer equal to the maximum nesting depth of parentheses in that group.
    """
    results = []
    groups = paren_string.split()
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        results.append(max_depth)
    return results


