def anti_shuffle(s):
    """
    Sort each word independently by ASCII order, preserving spaces as separators in their original positions.
    """
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)


