def count_upper(s):
    """
    Count the number of uppercase vowels A, E, I, O, U in string s
    only if they occur at even indices (0-based).
    """
    vowels = {'A', 'E', 'I', 'O', 'U'}
    return sum(1 for i, c in enumerate(s) if i % 2 == 0 and c in vowels)


