def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k containing the k largest elements from arr, including duplicates.
    If arr has fewer than k elements, return all elements sorted.
    """
    if k <= 0:
        return []
    # Sort the array in descending order to pick the k largest elements including duplicates
    largest_k = sorted(arr, reverse=True)[:k]
    # Return them sorted ascending
    return sorted(largest_k)


