def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit after '-' is negative
            first_digit = -int(s[1])
            rest_digits = s[2:]
            return first_digit + sum(int(d) for d in rest_digits)
        else:
            return sum(int(d) for d in s)
    return [x for _, x in sorted(enumerate(nums), key=lambda ix: (digit_sum(ix[1]), ix[0]))]


