def parse_nested_parens(paren_string):
    """
    Given a string containing any characters, split it by spaces into groups,
    and for each group (assumed balanced), return the maximum depth of nested parentheses.
    Returns a list of integers, one per space-separated group.
    """
    result = []
    groups = paren_string.split()
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result


