from typing import List

def parse_music(s: str) -> List[int]:
    beats = []
    i = 0
    while i < len(s):
        if s[i:i+2] == 'o|':
            beats.append(2)
            i += 2
        elif s[i:i+2] == '.|':
            beats.append(1)
            i += 2
        elif s[i] == 'o':
            beats.append(4)
            i += 1
        else:
            i += 1  # skip any unrecognized characters
    return beats


