def smallest_change(arr):
    """
    Return the count of mismatched pairs in symmetric positions in the array,
    where each mismatched pair requires exactly one element change to fix.
    """
    n = len(arr)
    count = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count


