from typing import List

def max_fill(grid: List[List[int]], capacity: int) -> int:
    total_buckets = 0
    for row in grid:
        water_units = sum(row)
        if water_units > 0:
            total_buckets += math.ceil(water_units / capacity)
    return total_buckets


