def digits(n):
    """Given an integer n, return the product of the odd digits in the absolute value of n,
    or 0 if there are no odd digits."""
    product = 1
    found_odd = False
    for ch in str(abs(n)):
        d = int(ch)
        if d % 2 == 1:
            product *= d
            found_odd = True
    return product if found_odd else 0


