def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        first_digit = int(s[0])
        first_digit = first_digit if n >= 0 else -first_digit
        rest = sum(int(d) for d in s[1:])
        return first_digit + rest
    return sorted(nums, key=digit_sum)


