from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Given a string containing groups of nested parentheses separated by literal space characters,
    return a list of integers representing the maximum nesting depth for each group.

    Groups are split by spaces. Each group is processed independently.
    For each group:
      - If parentheses are balanced, return the maximum nesting depth.
      - If unbalanced at any point, reset the depth count and continue parsing the group,
        effectively ignoring unbalanced sequences.
      - The maximum depth reflects only balanced sections within the group.

    Args:
        paren_string: str, input string containing groups separated by spaces.

    Returns:
        List[int]: list of maximum nesting depths, one per group.
    """
    result = []
    groups = paren_string.split(' ')
    for group in groups:
        if not group:
            # Skip empty groups (from multiple spaces)
            continue
        max_depth = 0
        current_depth = 0
        balanced = True
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
                if current_depth < 0:
                    # Unbalanced closing paren, reset current_depth and continue
                    current_depth = 0
                    balanced = False
            else:
                # Ignore any non-parenthesis chars inside groups as per spec (shouldn't appear)
                pass
        # If after processing group current_depth != 0, group is unbalanced
        # According to spec, ignore unbalanced sequences by resetting depth on errors
        # So max_depth reflects max nesting of balanced subsequences only
        # So no further action needed here

        # Append max_depth even if group is unbalanced, as max_depth tracks max balanced depth segments
        result.append(max_depth)
    return result


