def monotonic(l: list) -> bool:
    if not l:
        return True
    nondecreasing = True
    nonincreasing = True
    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            nondecreasing = False
        if l[i] > l[i - 1]:
            nonincreasing = False
    return nondecreasing or nonincreasing


