def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if n == 0:
        return s
    shift = shift % n
    if shift == 0:
        return s
    # A positive shift means rotate right by shift places
    # Right rotation by shift is equivalent to taking last shift chars to front
    return s[-shift:] + s[:-shift]


