import re

def anti_shuffle(s):
    # Split the string into sequences of words and spaces
    tokens = re.findall(r'\S+|\s+', s)
    result_tokens = []
    for token in tokens:
        if token.isspace():
            # preserve spaces as is
            result_tokens.append(token)
        else:
            # sort all characters in the word ascending by ASCII
            sorted_chars = ''.join(sorted(token))
            result_tokens.append(sorted_chars)
    return ''.join(result_tokens)


