def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Helper to check if a list is non-decreasing
    def is_non_decreasing(lst):
        return all(lst[i] <= lst[i+1] for i in range(len(lst)-1))

    # Try all right rotations
    for r in range(n):
        rotated = arr[-r:] + arr[:-r]
        if is_non_decreasing(rotated):
            return True

    return False


