def candidate(nums):
    """
  Write a function which sorts the given list of integers
  in descending or ascending order according to the sum of their digits.
  Note: if there are several items with similar sum of their digits,
  order them based on their index in original list.

  For example:
  >>> candidate([1, 11, -1, -11, -12]) == [1, 11, -1, -12, -11]
  >>> candidate([]) == []
  """


def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        if n < 0:
            # first digit counted negatively
            first_digit = -int(s[0])
            rest = sum(int(d) for d in s[1:])
            return first_digit + rest
        else:
            return sum(int(d) for d in s)
    indexed = list(enumerate(nums))
    # Sort by digit_sum ascending, tie break by original index ascending
    return sorted(indexed, key=lambda x: (digit_sum(x[1]), x[0]))


