def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        return 0
    # factorial(b) / factorial(a) = (a+1)*(a+2)*...*b
    # We want the last digit of that product.
    product = 1
    for x in range(a + 1, b + 1):
        product = (product * (x % 10)) % 10
        # Once product is 0 mod 10, last digit is 0 permanently
        if product == 0:
            return 0
    return product


