def zip_tuples(*tuples):
    if not tuples:
        return ()
    first, *rest = tuples
    length = len(first)
    result = []
    for i in range(length):
        zipped = [first[i]]
        for t in rest:
            zipped.append(t[i % len(t)] if t else None)
        result.append(tuple(zipped))
    return tuple(result)


