def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Special case: if all digits are '9', next palindrome is 10..01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, middle: str, odd_length: bool) -> str:
        if odd_length:
            return left + middle + left[::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    mid_index = length // 2

    left = s[:mid_index]
    middle = s[mid_index] if odd else ''
    right = s[mid_index+1:] if odd else s[mid_index:]

    # Form the palindrome by mirroring left + middle
    palindrome = make_palindrome(left, middle, odd)
    palindrome_int = int(palindrome)

    if palindrome_int > num:
        return palindrome_int
    else:
        # Need to increment the palindrome's middle part
        if odd:
            # Increment the middle digit and fix carry if needed
            left_middle_num = left + middle
            increment_part = int(left_middle_num) + 1
            increment_str = str(increment_part)

            # If incrementing caused length increase (e.g. 999 -> 1000)
            if len(increment_str) > len(left_middle_num):
                # This means the palindrome length increases by 1
                # For example: 999 -> next palindrome 1001
                # Construct palindrome with new left and empty middle
                left = increment_str[:-1]
                middle = increment_str[-1]
            else:
                left = increment_str[:-1]
                middle = increment_str[-1]

            palindrome = make_palindrome(left, middle, odd)
            return int(palindrome)
        else:
            # Even length: increment the left half and mirror
            increment_part = int(left) + 1
            increment_str = str(increment_part)

            # If length increased due to increment (e.g. 99 -> 100)
            if len(increment_str) > len(left):
                # Palindrome length increases by 1
                # For example: 99 -> 101
                palindrome = '1' + ('0' * (length -1)) + '1'
                return int(palindrome)
            else:
                left = increment_str
                palindrome = make_palindrome(left, '', False)
                return int(palindrome)


