def find_solution(a: int, b: int, n: int):
    # Try x from 0 upwards, check if y = (n - a*x)/b is a non-negative integer
    if b == 0:
        # If b == 0, then equation is a*x = n
        if a == 0:
            # a=0, b=0 => equation 0= n; only solution if n=0
            if n == 0:
                return (0, 0)
            else:
                return "No solution"
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
            else:
                return "No solution"
        else:
            return "No solution"

    if a == 0:
        # Then equation is b*y = n
        if n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
            else:
                return "No solution"
        else:
            return "No solution"

    # Both a and b nonzero
    x = 0
    while True:
        diff = n - a * x
        if diff < 0:
            # Since a*x grows with x, no larger x will help
            break
        if diff % b == 0:
            y = diff // b
            if y >= 0:
                return (x, y)
        x += 1

    return "No solution"


