def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 0
    # dp[i][x]: number of sequences of length i+1 ending with x (1-based indexing)
    # i from 0 to n-1, x from 1 to m
    dp = [0] * (m + 1)
    # For sequences of length 1, any starting value from 1 to m is allowed
    for x in range(1, m + 1):
        dp[x] = 1

    for i in range(1, n):
        new_dp = [0] * (m + 1)
        # prefix sums of dp for efficient computation
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]

        for x in range(1, m + 1):
            min_next = 2 * x
            if min_next <= m:
                # sum dp[y] for y >= min_next
                new_dp[x] = prefix[m] - prefix[min_next - 1]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:])  # sum over all sequences of length n ending with any valid last element


