def even_binomial_Coeff_Sum(n: int) -> int:
    # The sum of binomial coefficients C(n, k) for even k is known to be 2^(n-1) for n >= 1,
    # and 1 for n=0 (since C(0,0) = 1).
    if n == 0:
        return 1
    return 2 ** (n - 1)


