from typing import List, Any

def remove_column(lst: List[List[Any]], col: int) -> List[List[Any]]:
    result = []
    for row in lst:
        if col < 0 or col >= len(row):
            raise IndexError(f"Column index {col} out of range for row {row}")
        # Build new row without the element at index col
        new_row = row[:col] + row[col+1:]
        result.append(new_row)
    return result


