def permute_string(s: str) -> None:
    def backtrack(path, counter):
        if len(path) == len(s):
            print("".join(path))
            return
        for char in counter:
            if counter[char] > 0:
                path.append(char)
                counter[char] -= 1
                backtrack(path, counter)
                counter[char] += 1
                path.pop()

    from collections import Counter
    counter = Counter(s)
    backtrack([], counter)


