from typing import List, Optional

def find_Max(arr: List[int], low: int, high: int) -> Optional[int]:
    if low > high:
        return None
    if low == high:
        return arr[low]

    # If array is not rotated (sorted ascending)
    if arr[low] < arr[high]:
        return arr[high]

    while low < high:
        mid = (low + high) // 2
        # If mid element is greater than its next element, mid is max
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # If mid element is smaller than its previous element, mid-1 is max
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        # Decide which side to go
        if arr[mid] > arr[low]:
            low = mid + 1
        else:
            high = mid - 1

    return arr[low]


