def sum_digits(n: int) -> int:
    s = str(n)
    # The first digit may be negative if n is negative
    if s[0] == '-':
        first_digit = -int(s[1])
        rest_digits = s[2:]
    else:
        first_digit = int(s[0])
        rest_digits = s[1:]
    return first_digit + sum(int(d) for d in rest_digits)


