from typing import List

def reverse_Array_Upto_K(arr: List[int], k: int) -> List[int]:
    if k < 0:
        return arr[:]
    n = len(arr)
    if k > n:
        k = n
    # Reverse first k elements (1-based semantics: first k elements mean indices 0 through k-1)
    return arr[:k][::-1] + arr[k:]


