def capital_words_spaces(s: str) -> str:
    if not s:
        return s

    result = [s[0]]
    i = 1
    length = len(s)

    while i < length:
        c = s[i]
        prev = s[i - 1]

        if c.isupper() and prev.isalnum():
            # Check if this uppercase letter is part of an acronym (consecutive uppercase letters)
            # Look ahead to see if next char is uppercase as well
            j = i
            while j + 1 < length and s[j + 1].isupper():
                j += 1
            # Insert space before the whole acronym if it is more than one letter
            if j > i:
                # Insert space before the acronym start, then append the acronym as is
                result.append(' ')
                result.append(s[i:j + 1])
                i = j + 1
                continue
            else:
                # Single uppercase letter preceded by a word char, add space before it
                result.append(' ')
                result.append(c)
                i += 1
                continue
        else:
            result.append(c)
            i += 1

    return ''.join(result)


