def lucky_num(n: int) -> list[int]:
    """
    Return the first n lucky numbers defined by the classical sieve method.

    The classical lucky numbers are generated by a sieve similar to the sieve of Eratosthenes:
    - Start with the list of positive integers: 1, 2, 3, 4, 5, ...
    - The first lucky number is 1.
    - Remove every 2nd number from the list (because the first number after 1 is 2).
    - The next number in the list after 1 is 3, so remove every 3rd number.
    - The next surviving number after that is 7, so remove every 7th number.
    - Continue this process until you have at least n lucky numbers.

    Args:
        n (int): Number of lucky numbers to return.

    Returns:
        list[int]: The first n lucky numbers.
    """
    if n <= 0:
        return []

    # We will start with a sufficiently large list of integers.
    # Since lucky numbers are sparse, start with a list size roughly 3*n to ensure enough lucky numbers.
    size = max(50, n * 3)
    numbers = list(range(1, size + 1))

    idx = 1  # start from the second element (index 1), because first lucky number is numbers[0] = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number, counting from index 0 (1-based indexing for removal)
        # The first removal is at index = step - 1, then step-1 + step, etc.
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n and idx >= n:
            # We have enough lucky numbers to return
            break
        # If list becomes too short to get n lucky numbers, extend and continue
        if len(numbers) < n:
            size *= 2
            # Extend numbers by appending integers after the last element
            last = numbers[-1]
            numbers.extend(range(last + 1, last + (size - len(numbers)) + 1))

    return numbers[:n]


