def compute_Last_Digit(a: int, b: int) -> int:
    """
    Returns the last digit (including zeros) of factorial(b) // factorial(a),
    given that factorial(a) divides factorial(b).
    """
    # factorial(b) // factorial(a) = product of integers from a+1 to b
    result = 1
    for x in range(a + 1, b + 1):
        result *= x

    return result % 10


