from itertools import cycle

def zip_tuples(groups):
    if not groups:
        return []
    n = len(groups[0])
    result = []
    for i in range(n):
        tup = []
        for group in groups:
            if len(group) == 0:
                # If any group is empty, can't cycle; just skip or produce None
                # but spec doesn't say, so just skip (no elements)
                tup.append(None)
            elif len(group) < n:
                tup.append(group[i % len(group)])
            else:
                tup.append(group[i])
        result.append(tuple(tup))
    return result


