def Find_Min_Length(groups):
    """
    Given groups (a list of list of iterables), returns the single smallest length 
    among all parts in all groups combined. If there is only one group, returns 
    that group's smallest length as an integer.

    If groups is empty or contains empty sublists, the behavior naturally follows 
    from the min function (will raise ValueError if no iterable parts exist).
    """
    # Flatten all parts from all groups into a single iterable and get their lengths
    all_lengths = (len(part) for group in groups for part in group)
    return min(all_lengths)


