def next_smallest_palindrome(num: int) -> int:
    """
    Return the smallest palindrome strictly greater than the given number num.
    If no such palindrome exists (which practically won't happen for int),
    return -1.
    """

    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    s = str(num)
    length = len(s)

    # Handle single digit separately
    if length == 1:
        if num < 9:
            return num + 1
        else:
            # For 9, next palindrome is 11
            return 11

    # If all digits are 9, e.g. 9, 99, 999, next palindrome is 10..01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    half_len = (length + 1) // 2
    left = s[:half_len]

    # Make palindrome from left half
    candidate = make_palindrome(left, length % 2 != 0)
    if candidate > num:
        return candidate

    # Increment the left half and form palindrome again
    left_num = int(left) + 1
    left_str = str(left_num)

    # If incrementing left changes length (e.g. 999 -> 1000)
    if len(left_str) > len(left):
        # This means the palindrome length increases by 1
        # For example 999 -> 1001
        return int('1' + ('0' * (length -1)) + '1')

    return make_palindrome(left_str, length % 2 != 0)


