def sort_sublists(lst):
    """
    Sort each sublist individually, treating each item in the sublist as an iterable,
    and sorting the sublist based on the first element of each item.

    Parameters:
        lst (list of lists): A list of sublists, where each sublist contains items that are themselves iterable,
                             and each item has a first element.

    Returns:
        list of lists: A new list of sublists, each sorted by the first element of its items.
    """
    return [sorted(sublist, key=lambda x: x[0]) for sublist in lst]


