def next_power_of_2(n: int) -> int:
    if n <= 0:
        return 1
    # If n is already a power of two, return n
    if (n & (n - 1)) == 0:
        return n
    # Otherwise, find next power of two
    power = 1
    while power < n:
        power <<= 1
    return power


