def get_total_number_of_sequences(limit: int) -> int:
    # dp[i] = number of sequences starting at i
    dp = [0] * (limit + 2)  # +2 to avoid index issues

    # For each starting number from limit down to 1
    for i in range(limit, 0, -1):
        total = 1  # sequence consisting of only i
        # Next elements must be at least double the previous
        next_start = 2 * i
        for next_elem in range(next_start, limit + 1):
            total += dp[next_elem]
        dp[i] = total

    return sum(dp[1 : limit + 1])


