import re

def text_match_two_three(s: str) -> bool:
    # Pattern: 'a' followed by at least two and up to three 'b's
    # Longer sequences with more than three 'b's still count as a match if they contain this substring.
    # So we search for substring 'a' + 'bb' or 'a' + 'bbb' anywhere in s.
    return bool(re.search(r"ab{2,3}", s))


