def smallest_missing(arr, start=0, end=None):
    if end is None:
        end = len(arr)
    # operate on subrange arr[start:end]
    # arr is sorted, distinct, non-negative integers starting at 0

    # If subrange is empty, smallest missing is 0
    if start >= end:
        return 0

    # Length of subrange
    length = end - start

    # Binary search for smallest missing number in arr[start:end]
    left, right = start, end
    while left < right:
        mid = (left + right) // 2
        expected = mid - start
        if arr[mid] == expected:
            left = mid + 1
        else:
            right = mid
    return left - start


