from typing import List

def permute_string(text: str) -> List[str]:
    def backtrack(path, used):
        if len(path) == len(text):
            result.append(''.join(path))
            return
        for i in range(len(text)):
            if not used[i]:
                used[i] = True
                path.append(text[i])
                backtrack(path, used)
                path.pop()
                used[i] = False

    result = []
    used = [False] * len(text)
    backtrack([], used)
    return result


