def find_Max(seq, start, end):
    """Return the maximum element in seq[start:end]."""
    if start >= end:
        # empty slice, no elements
        return None
    max_val = seq[start]
    for i in range(start + 1, end):
        if seq[i] > max_val:
            max_val = seq[i]
    return max_val


