import ast

def str_to_tuple(s: str) -> tuple[int, ...]:
    def flatten(obj):
        if isinstance(obj, int):
            return [obj]
        elif isinstance(obj, (list, tuple)):
            result = []
            for item in obj:
                result.extend(flatten(item))
            return result
        else:
            # If the input contains unexpected types (e.g., strings), ignore them
            return []
    parsed = ast.literal_eval(s)
    flat_list = flatten(parsed)
    return tuple(flat_list)


