def check_Even_Parity(n: int) -> bool:
    # Count the number of set bits (1s) in the binary representation of the absolute value of n
    count_ones = bin(abs(n)).count('1')
    # Return True if the count of set bits is even, False otherwise
    return (count_ones % 2) == 0


