def lucky_num(n: int) -> list[int]:
    if n <= 0:
        return []
    # Initial list of natural numbers starting from 1
    numbers = list(range(1, n * 20))  # Overestimate size to ensure enough lucky numbers

    idx = 1  # Start from second element (index 1), since the first lucky number is 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based indexing)
        # Using 0-based indexing: remove elements at indices step-1, 2*step-1, ...
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx >= n:  # Optimization: stop if we have enough and index passed n
            break
    return numbers[:n]


