from itertools import cycle

def zip_tuples(t1: tuple, t2: tuple) -> tuple:
    if len(t1) >= len(t2):
        longer, shorter = t1, t2
    else:
        longer, shorter = t2, t1
    cycled_shorter = cycle(shorter)
    return tuple((longer[i], next(cycled_shorter)) if longer is t1 else (next(cycled_shorter), longer[i]) for i in range(len(longer)))


