def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all digits are '9', the next palindrome is 10...01 (length+1 digits)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def make_palindrome_left_to_right(left: str, length: int) -> str:
        # Construct palindrome by mirroring left to right half
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[-2::-1]

    # Get left half (including middle if odd length)
    if length % 2 == 0:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]
    else:
        left = s[:length // 2 + 1]
        middle = left[-1]
        right = s[length // 2 + 1:]

    # Make a palindrome by mirroring left half
    palindrome = make_palindrome_left_to_right(left, length)

    if int(palindrome) > n:
        return int(palindrome)

    # Need to increment the middle part and then mirror again
    if length % 2 == 0:
        # Even length
        # Increment left half as a number
        incremented_left = str(int(left) + 1)
        # If length changes, means something like 99->100, so handle separately
        if len(incremented_left) > len(left):
            # Example: n=9999 -> next palindrome 10001 handled above, but just in case
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = make_palindrome_left_to_right(incremented_left, length)
        return int(palindrome)
    else:
        # Odd length
        # Increment left half as a number
        incremented_left = str(int(left) + 1)
        if len(incremented_left) > len(left):
            # Example: 999 -> 1001 handled above, but just in case
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = make_palindrome_left_to_right(incremented_left, length)
        return int(palindrome)


