def find_solution(a: int, b: int, n: int):
    # Extended Euclidean Algorithm to find gcd and x,y such that a*x + b*y = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    # Handle trivial case
    if n == 0:
        if a == 0 and b == 0:
            # infinite solutions but return (0,0)
            return (0, 0)
        if a == 0:
            if n % b == 0 and n // b >= 0:
                return (0, n // b)
            return None
        if b == 0:
            if n % a == 0 and n // a >= 0:
                return (n // a, 0)
            return None
        return (0, 0)  # x=0,y=0 is solution for n=0

    # If both a and b are zero but n != 0, no solution
    if a == 0 and b == 0:
        return None

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return None

    # Scale the solution to n/gcd
    x0 *= n // gcd
    y0 *= n // gcd

    # Adjust signs according to original a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # a and b divided by gcd
    a_div = a // gcd
    b_div = b // gcd

    # The general solution is:
    # x = x0 + k*(b/gcd)
    # y = y0 - k*(a/gcd)
    #
    # We want x >= 0 and y >= 0
    #
    # Solve inequalities for k:
    # x0 + k*(b/gcd) >= 0  =>  k >= -x0 * gcd / b
    # y0 - k*(a/gcd) >= 0  =>  k <= y0 * gcd / a

    # Because a_div and b_div can be negative, we carefully handle inequalities:

    # For x >= 0:
    if b_div != 0:
        if b_div > 0:
            k_min = (-x0 + b_div - 1) // b_div  # ceil division for k >=
        else:
            k_max = (-x0) // b_div  # floor division for k <=
    else:
        # b_div == 0 means x = x0 fixed, must be >= 0
        if x0 < 0:
            return None

    # For y >= 0:
    if a_div != 0:
        if a_div > 0:
            k_max_y = y0 // a_div  # floor division for k <=
        else:
            k_min_y = (y0 + (-a_div) - 1) // (-a_div)  # ceil division for k >=
    else:
        # a_div == 0 means y = y0 fixed, must be >= 0
        if y0 < 0:
            return None

    # Now combine constraints on k:

    # Initialize k_min and k_max with None and then assign based on cases
    k_min_val = None
    k_max_val = None

    # From x >= 0:
    if b_div > 0:
        k_min_val = (-x0 + b_div - 1) // b_div
    elif b_div < 0:
        k_max_val = (-x0) // b_div
    else:
        # b_div == 0 handled above
        pass

    # From y >= 0:
    if a_div > 0:
        if k_max_val is None:
            k_max_val = y0 // a_div
        else:
            k_max_val = min(k_max_val, y0 // a_div)
    elif a_div < 0:
        if k_min_val is None:
            k_min_val = (y0 + (-a_div) - 1) // (-a_div)
        else:
            k_min_val = max(k_min_val, (y0 + (-a_div) - 1) // (-a_div))
    else:
        # a_div == 0 handled above
        pass

    # Now find k such that k_min_val <= k <= k_max_val
    if k_min_val is None:
        k_min_val = -10**18  # very small number
    if k_max_val is None:
        k_max_val = 10**18   # very large number

    if k_min_val > k_max_val:
        return None

    # Pick k = k_min_val as a valid k (smallest k satisfying constraints)
    k = k_min_val

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        # Try k+1 if possible
        k = k_min_val + 1
        if k <= k_max_val:
            x = x0 + k * b_div
            y = y0 - k * a_div
            if x >= 0 and y >= 0:
                return (x, y)
        return None

    return (x, y)


