def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 1  # Empty sequence counts as 1 sequence
    # dp[i][x] = number of sequences of length i ending with value x
    dp = [ [0] * (m + 1) for _ in range(n + 1) ]

    # Base case: sequences of length 1
    for x in range(1, m + 1):
        dp[1][x] = 1

    for i in range(2, n + 1):
        for x in range(1, m + 1):
            # Previous element y must satisfy: y == x or y == 2*x or x == 2*y
            # So dp[i][x] = sum of dp[i-1][y] for all y where y==x or y==2*x or x==2*y and y in [1,m]

            total = dp[i-1][x]  # y == x

            if 2 * x <= m:
                total += dp[i-1][2 * x]  # y == 2*x

            if x % 2 == 0:
                half = x // 2
                if 1 <= half <= m:
                    total += dp[i-1][half]  # x == 2*y => y == x//2

            dp[i][x] = total

    return sum(dp[n][1:])  # sum over all sequences of length n ending with any value in [1,m]


