def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            depth = dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        # Do not traverse dicts inside lists or tuples per clarification
        # So skip lists and tuples entirely
    return 1 + max_depth


