def smallest_missing(arr: list[int], low: int, high: int) -> int:
    """
    Find the smallest non-negative integer missing from arr[low:high+1],
    assuming arr is sorted with arr[i] == i for the entire array.

    Uses binary search on indices [low, high], comparing arr[mid] with mid.

    Returns the smallest missing integer in that index range.
    """
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == mid:
            low = mid + 1
        else:
            high = mid - 1
    return low


