def add_string(lst, fmt):
    # Count the number of substitution slots '{}' in fmt
    # We consider only '{}' pairs, not other format specifiers.
    # To do this safely, we can use str.format_map and manually count,
    # but simpler is to count occurrences of '{}' substring not escaped.
    # However, '{}' can be escaped as '{{}}' and so on.
    # The canonical way is to use string.Formatter.parse to count fields.

    from string import Formatter

    formatter = Formatter()
    slots = 0
    for _, field_name, _, _ in formatter.parse(fmt):
        if field_name is not None:
            slots += 1

    if slots == 0:
        # no substitution slot, return list of fmt repeated len(lst) times
        return [fmt] * len(lst)
    if slots != 1:
        raise ValueError("Format string must contain exactly one substitution slot")
    return [fmt.format(s) for s in lst]


