from typing import List, Optional

def find_Max(arr: List[int]) -> Optional[int]:
    if not arr:
        return None
    left, right = 0, len(arr) - 1

    # If array is not rotated (sorted ascending), the max is the last element
    if arr[left] < arr[right]:
        return arr[right]

    # Binary search for maximum element
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than right element,
        # max must be in left to mid
        if arr[mid] > arr[right]:
            left = mid
        else:
            # max is in left to mid-1
            right = mid - 1

    return arr[left]


