import re

def text_match(text: str) -> bool:
    # Match strings that start with 'a' followed by zero or more 'b's,
    # but only if no additional 'b' immediately follows the matched sequence.
    # That means the matched sequence is 'a' + (some b's),
    # and the next character after the last 'b' is not 'b' (or string end).
    #
    # We must match the entire string (full match).
    #
    # Pattern breakdown:
    # ^a          : starts with 'a'
    # b*          : zero or more 'b's
    # (?!b)       : negative lookahead, next char after matched b's is NOT 'b'
    # $           : end of string
    #
    # This ensures no extra 'b' after the matched sequence.
    return bool(re.fullmatch(r'a b* (?!b) ', text, re.VERBOSE))


