def filter_data(data, height_threshold, width_threshold):
    """
    Filters the input dictionary of student attributes and returns a new dictionary
    containing only those students whose 'height' is at least height_threshold
    and 'width' is at least width_threshold.

    Args:
        data (dict): Dictionary with keys including 'height' and 'width'.
        height_threshold (int or float): Minimum height to filter.
        width_threshold (int or float): Minimum width to filter.

    Returns:
        dict: A new dictionary containing only 'height' and 'width' entries from the input
              if they meet the thresholds; otherwise, returns an empty dictionary.
    """
    height = data.get('height')
    width = data.get('width')

    if height is not None and width is not None:
        if height >= height_threshold and width >= width_threshold:
            return {'height': height, 'width': width}
    return {}


