def is_triangleexists(a: float, b: float, c: float) -> bool:
    """
    Determine if three angles can form a positive-area triangle.

    Conditions:
    - All angles must be positive.
    - The sum of the angles must be exactly 180 degrees.

    Args:
        a (float): Angle 1 in degrees.
        b (float): Angle 2 in degrees.
        c (float): Angle 3 in degrees.

    Returns:
        bool: True if angles form a valid triangle, False otherwise.
    """
    return a > 0 and b > 0 and c > 0 and abs((a + b + c) - 180) < 1e-9


