def lucky_num(n):
    # Start with the list of lucky numbers initialized with 1
    lucky_numbers = [1]
    # We generate candidates starting from 2 upwards
    candidate = 2

    while len(lucky_numbers) < n:
        # Check if candidate is lucky:
        # A lucky number is one that survives the sieve process:
        # For each lucky number > 1, remove every kth number where k is that lucky number.
        # To check candidate, we simulate the sieve on the fly:
        # If candidate is removed by any lucky number divisor, it is not lucky.
        is_lucky = True
        for ln in lucky_numbers[1:]:  # skip the first lucky number 1
            if ln > candidate:
                break
            if candidate % ln == 0:
                is_lucky = False
                break
        if is_lucky:
            lucky_numbers.append(candidate)
        candidate += 1

    return lucky_numbers


