def dif_Square(n: int) -> bool:
    # A number n can be expressed as difference of squares if and only if
    # n is not congruent to 2 mod 4.
    # This is because difference of squares: a^2 - b^2 = (a+b)(a-b).
    # Both (a+b) and (a-b) have the same parity, so n = product of two integers with same parity.
    # Numbers congruent to 2 mod 4 cannot be expressed as difference of squares.
    return n % 4 != 2


