def next_smallest_palindrome(num: int) -> int:
    if num < 0:
        return 0

    s = str(num + 1)  # start checking from the next integer
    length = len(s)

    while True:
        # Make a palindrome by mirroring the left half onto the right half
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            palindrome = left + left[::-1]
        else:
            palindrome = left + left[-2::-1]

        palindrome_num = int(palindrome)
        if palindrome_num > num:
            return palindrome_num

        # Increment the left half and try to form a bigger palindrome
        left_num = int(left) + 1
        left = str(left_num)

        # If incrementing left changes its length, it means palindrome length increases by 1
        if len(left) > half:
            # For example, 999 -> 1000 means next palindrome is 10001
            length += 1
            s = '1' + ('0' * (length - 1))
        else:
            s = left + s[half:]


