def find_solution(a: int, b: int, n: int):
    if b == 0:
        # equation is a*x = n
        # find non-negative integer x starting at 0 with y integer
        # y is not defined if b=0, so y must be 0 and check if a*x = n
        # but per problem, y must be computed accordingly
        # With b=0, equation is a*x = n => if n % a == 0 and x >= 0, y can be 0
        if a == 0:
            # then equation is 0 = n, so solution if n==0
            if n == 0:
                return ('x = ', 0, ', y = ', 0)
            else:
                return "No solution"
        for x in range(max(0, n // a + 1)):
            if a * x == n:
                y = 0
                return ('x = ', x, ', y = ', y)
        return "No solution"

    # For b != 0
    # We try x from 0 upwards, compute y = (n - a*x)/b
    # y must be integer and >= 0
    x = 0
    # upper bound for x can be heuristically n//a if a>0, else try until no solution found
    # but safer to loop until x where a*x > n and a,b positive,
    # or up to a reasonable large value to avoid infinite loop if a or b negative.
    # Since no maximum is specified, loop until no solution possible
    # To avoid infinite loop, use a limit based on n and a,b
    # If a>0, max_x = n // a if n >= 0 else 0
    # If a<=0, max_x = max(0, n // a) might not be meaningful, so we can try up to some limit

    # Let's determine a reasonable search limit:
    # Because x must be >=0, and y must be integer and >=0
    # a*x <= n (if a>0), else no upper bound from this side
    # similarly for b*y = n - a*x, y >= 0 => n - a*x >= 0 if b>0
    # So for b>0: n - a*x >= 0 => x <= n/a if a>0

    # We'll set max_x to max(0, n//a) if a>0 else 100000 (arbitrary large limit)
    max_iter = 1000000
    if a > 0:
        max_x = n // a
        if max_x < 0:
            return "No solution"
        max_iter = max_x + 1

    for x in range(max_iter):
        remainder = n - a * x
        if remainder < 0 and b > 0:
            # since y = remainder/b, if remainder < 0 and b > 0, y < 0 no solution
            break
        if b == 0:
            # handled above, but just in case
            continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
    return "No solution"


