def text_match_two_three(text: str):
    if "aa" in text:
        # Check if there is exactly 2 or 3 consecutive 'a's
        for i in range(len(text)):
            if text[i] == 'a':
                count = 1
                j = i + 1
                while j < len(text) and text[j] == 'a':
                    count += 1
                    j += 1
                if count == 2 or count == 3:
                    return True
    return 'Not matched!'


