from typing import List

def permute_string(s: str) -> List[str]:
    def backtrack(path, counter, length, res):
        if len(path) == length:
            res.append("".join(path))
            return
        for ch in counter:
            if counter[ch] > 0:
                path.append(ch)
                counter[ch] -= 1
                backtrack(path, counter, length, res)
                counter[ch] += 1
                path.pop()

    from collections import Counter
    counter = Counter(s)
    result = []
    backtrack([], counter, len(s), result)
    return result


