def find_Max(arr, start, end):
    if start > end:
        return None  # or could be float('-inf') depending on interpretation
    max_val = arr[start]
    for i in range(start + 1, end + 1):
        if arr[i] > max_val:
            max_val = arr[i]
    return max_val


