def odd_length_sum(arr: list[int]) -> int:
    if not arr:
        return 0
    total = 0
    n = len(arr)
    for length in range(1, n + 1, 2):  # only odd lengths
        for start in range(n - length + 1):
            total += sum(arr[start:start + length])
    return total


