def lucky_num():
    """
    Generate an infinite sequence of lucky numbers using the sieve of lucky numbers.

    Lucky numbers are generated by a sieve similar to the sieve of Eratosthenes:
    1. Start with the list of natural numbers starting at 1.
    2. The first lucky number is 1.
    3. The second lucky number is 3, so remove every 3rd number from the list.
    4. The next lucky number is the next number in the list after 3 (which is 7),
       so remove every 7th number from the list.
    5. Repeat this process indefinitely.

    This function yields lucky numbers indefinitely.
    """
    nums = list(range(1, 10**6))  # Start with 1 million numbers to avoid infinite memory growth
    idx = 1  # Start from second element (index 1, value 3)
    while idx < len(nums):
        step = nums[idx]
        yield nums[0]
        nums = [nums[i] for i in range(len(nums)) if (i + 1) % step != 0]
        idx += 1
    # If the list is exhausted, stop iteration


