def get_noOfways(n: int) -> int:
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n == 1:
        return 1

    prev_prev = 1  # ways to tile 2x0 board
    prev = 1       # ways to tile 2x1 board

    for _ in range(2, n + 1):
        current = prev + prev_prev
        prev_prev, prev = prev, current

    return prev


