def dif_Square(n: int) -> bool:
    # An integer n can be written as a difference of squares of two integers
    # if and only if n is NOT congruent to 2 modulo 4.
    # Proof outline:
    # Any square is congruent to 0 or 1 mod 4.
    # Difference of squares mod 4 can be 0, 1, or 3, but never 2.
    return n % 4 != 2


