def next_smallest_palindrome(num: int) -> int:
    """
    Find the next smallest palindrome strictly greater than num.
    """
    s = str(num)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome is 10...01 (length+1 digits)
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    mid = length // 2

    # Extract left half (+ middle if odd)
    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    # Construct palindrome from left half
    palindrome = make_palindrome(left, odd)

    # If palindrome > num, return it
    if int(palindrome) > num:
        return int(palindrome)

    # Otherwise, increment the left half and then mirror again
    left_num = int(left)
    left_num += 1
    left = str(left_num)

    # Handle length increase after increment (e.g. 999 -> 1000)
    if len(left) > (mid + 1 if odd else mid):
        # This means palindrome length increases by 1
        # For example: 999 -> 1001 (length 3 -> 4)
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = make_palindrome(left, odd)
    return int(palindrome)


