def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        # Equation is b*y = n
        if b == 0:
            return None
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        return None
    if b == 0:
        # Equation is a*x = n
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    from math import gcd

    g = gcd(a, b)
    if n % g != 0:
        return None

    # We want to find nonnegative integers x,y satisfying a*x + b*y = n.
    # Iterate x from 0 upwards, compute y = (n - a*x)/b and check if integer and nonnegative.
    max_x = n // a if a > 0 else 0  # if a < 0, x starting at 0 and increasing will only decrease a*x, so no solutions.
    # But since we want smallest nonnegative x, we can try x from 0 up to max_x if a>0,
    # or try x from 0 upwards until the computed y becomes negative or no longer integer.
    # Similarly for negative a, the equation may not have any solution with x>=0.

    # To cover negative a or b, we can set a reasonable search limit:
    # For x>=0, (n - a*x)/b >= 0 => y >= 0
    # So for each x, check if y=(n - a*x)/b is integer and >=0.

    # To avoid infinite loop if b divides zero or negative, we can limit search:
    # Since x,y >=0 and integers, x can be at most n//a if a>0, or 0 if a<0 (since increasing x reduces a*x)
    # If a<0, increasing x from 0 upwards reduces a*x, so n - a*x grows, but since b*y = n - a*x,
    # y could be positive or negative depending on sign of b.

    # We'll try x from 0 up to a large enough bound:
    # For safety, try up to max(0, n // min(abs(a),1) + 1) to avoid division by zero.
    # But since a and b can be zero (already handled those cases), here min(abs(a),1) >=1.

    # Let's try x in range 0 to max_x_limit:
    max_x_limit = n if n > 0 else 0
    for x in range(max_x_limit + 1):
        numerator = n - a * x
        if b == 0:
            # Already handled above, but just in case.
            continue
        if numerator % b == 0:
            y = numerator // b
            if y >= 0:
                return (x, y)
    return None


