def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 0:
        return 0
    # dp[i][x]: number of sequences of length i+1 starting with x at position i
    # We'll use 0-based indexing for dp length dimension: i from 0 to n-1
    # For i=0 (first element), dp[0][x] = 1 for x in [1..m]
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1

    for i in range(1, n):
        new_dp = [0] * (m + 1)
        for prev in range(1, m + 1):
            if dp[prev] == 0:
                continue
            start = 2 * prev
            if start > m:
                continue
            # next elements can be from start to m
            # sum dp[prev] to new_dp[start..m]
            count = dp[prev]
            for nxt in range(start, m + 1):
                new_dp[nxt] += count
        dp = new_dp

    return sum(dp[1:]) if n > 0 else 0


