def min_flip_to_make_string_alternate(s: str) -> int:
    # Pattern 1: starting with '0' (e.g., 010101...)
    flips_start_with_0 = sum(ch != str(i % 2) for i, ch in enumerate(s))
    # Pattern 2: starting with '1' (e.g., 101010...)
    flips_start_with_1 = sum(ch != str((i + 1) % 2) for i, ch in enumerate(s))
    return min(flips_start_with_0, flips_start_with_1)


