def find_Max(arr, low, high):
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    # low is the index of the minimum element; maximum is just before it
    return arr[low - 1] if low > 0 else arr[-1]


