def even_Power_Sum(n: int) -> int:
    if n <= 0:
        return 0
    # Sum of fourth powers of first n even natural numbers:
    # even numbers: 2,4,6,...,2n
    # sum = Σ (2k)^4 = 16 * Σ k^4 for k=1 to n
    # Use formula for sum of fourth powers:
    # Σ k^4 = n(n+1)(2n+1)(3n^2+3n-1)/30
    s = n * (n + 1) * (2 * n + 1) * (3 * n * n + 3 * n - 1) // 30
    return 16 * s


