def filter_data(data):
    """
    Given a dictionary where each value is a 2-item sequence (height at index 0, width at index 1),
    return a new dictionary mapping each key to a dictionary with keys 'height' and 'width'.

    Example:
    input: {'student1': (170, 60), 'student2': [160, 55]}
    output: {'student1': {'height': 170, 'width': 60}, 'student2': {'height': 160, 'width': 55}}
    """
    return {k: {'height': v[0], 'width': v[1]} for k, v in data.items()}


