def lucky_num(n: int) -> list[int]:
    if n <= 0:
        return []
    # Start with odd numbers beginning at 1
    numbers = list(range(1, 2 * n * 10, 2))  # overshoot range to ensure enough numbers remain
    idx = 1  # start from second element (index 1), which determines the step for removal
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element, counting from index step-1 (0-based)
        # We keep elements whose (position+1) % step != 0
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n and idx >= n:
            break
    return numbers[:n]


