def dif_Square(n: int) -> bool:
    n = abs(n)
    # A number n can be represented as difference of two squares (a^2 - b^2)
    # if and only if n is NOT congruent to 2 modulo 4.
    # This is a known number theory result.
    return n % 4 != 2


