def zip_tuples(t1, t2):
    if not t1 and not t2:
        return []
    if len(t1) >= len(t2):
        longer, shorter = t1, t2
    else:
        longer, shorter = t2, t1
    result = []
    s_len = len(shorter)
    for i, elem in enumerate(longer):
        result.append((elem, shorter[i % s_len]))
    # If t1 is longer or equal, pairs are (t1_elem, t2_elem)
    # If t2 is longer, pairs are (t2_elem, t1_elem)
    # Adjust order to always be (t1_elem, t2_elem)
    if len(t1) >= len(t2):
        return result
    else:
        # Swap pairs to (t1_elem, t2_elem)
        return [(b, a) for a, b in result]


