def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle the special case where all digits are '9'
    if all(ch == '9' for ch in s):
        # The next palindrome greater than 999...9 is 100...001
        return int('1' + ('0' * (length - 1)) + '1')

    # Convert string to list of chars for easier manipulation
    s_list = list(s)

    # Find the next palindrome by mirroring the left half to the right
    mid = length // 2
    left = s_list[:mid]
    if length % 2 == 0:
        middle = ''
        right = s_list[mid:]
    else:
        middle = s_list[mid]
        right = s_list[mid+1:]

    # Construct palindrome by mirroring left + middle + reversed left
    if length % 2 == 0:
        palindrome = left + left[::-1]
    else:
        palindrome = left + [middle] + left[::-1]

    palindrome_num = int(''.join(palindrome))

    if palindrome_num > num:
        return palindrome_num

    # If palindrome_num <= num, we need to increment the middle part and then mirror again

    # Convert left+middle to a number to increment
    if length % 2 == 0:
        left_num = int(''.join(left))
        left_num += 1
        left_str = str(left_num)
        # If increment caused length increase, adjust accordingly
        if len(left_str) > len(left):
            # For example, 99 -> 100 means length increased
            # New palindrome will be 100001 (length+1)
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = list(left_str) + list(left_str[::-1])
    else:
        left_middle_num = int(''.join(left) + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)
        if len(left_middle_str) > len(left) + 1:
            # For example, 999 -> 1000 means length increased
            return int('1' + ('0' * (length -1)) + '1')
        left_str = left_middle_str[:-1]
        middle = left_middle_str[-1]
        palindrome = list(left_str) + [middle] + list(left_str[::-1])

    return int(''.join(palindrome))


