def find_solution(a: int, b: int, n: int):
    x = 0
    while True:
        remainder = n - a * x
        if b != 0 and remainder % b == 0:
            y = remainder // b
            return ('x = ', x, ', y = ', y)
        # If b == 0, then equation is ax = n; y is irrelevant
        if b == 0:
            if remainder == 0:
                return ('x = ', x, ', y = ', 0)
            else:
                # Since b=0 and remainder !=0, no solution for this x
                return 'No solution'
        x += 1
        # To avoid infinite loop, if x exceeds n and n>=0, no solution
        # But n can be negative, so set a reasonable upper bound or break condition
        # Since user didn't specify, we try up to abs(n)*2+1000 as a heuristic
        # If no solution found by then, return 'No solution'
        if x > abs(n) * 2 + 1000:
            return 'No solution'


