def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 0
    # dp[i][x]: number of sequences of length i starting with element x
    # For i=1, dp[1][x] = 1 for all x in [1..m]
    dp_prev = [1] * (m + 1)  # 1-based indexing, dp_prev[x] for i=1

    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # We want to find for each x in [1..m], 
        # number of sequences of length "length" starting at x
        # which equals sum of dp_prev[y] for y >= 2*x (and y <= m)
        # Because next element y >= 2*x
        # Precompute suffix sums of dp_prev to quickly sum dp_prev[y] for y >= some value
        suffix_sum = [0] * (m + 2)
        for x in range(m, 0, -1):
            suffix_sum[x] = suffix_sum[x + 1] + dp_prev[x]

        for x in range(1, m + 1):
            min_next = 2 * x
            if min_next <= m:
                dp_curr[x] = suffix_sum[min_next]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr

    return sum(dp_prev[1:]) if n > 0 else 0


