def smallest_missing(nums, left, right):
    """
    Finds the smallest missing non-negative integer in nums[left:right+1].
    nums is sorted in non-decreasing order.
    Negative integers are ignored.
    The search is restricted to the global indices from left to right inclusive.
    """
    # Restrict to the slice [left, right]
    # If slice empty, smallest missing is 0
    if left > right:
        return 0

    # Binary search for smallest missing number in range
    # The smallest missing number in the subarray can be found by comparing
    # the expected number at position i (starting from left) to the actual number.

    # We'll use an adapted binary search:
    # Since nums is sorted, ignoring negative numbers,
    # we want to find the smallest x >= 0 that is missing in nums[left:right+1].

    # Define a helper to count how many numbers >=0 and <= val exist in nums[left:right+1].
    # But that is not needed if we do binary search on the missing number directly.

    # Instead, we do binary search on the range of possible missing numbers.
    # The minimal missing number is in [0, max_val+1], 
    # where max_val = nums[right] if nums[right]>=0 else 0.

    max_val = nums[right] if nums[right] >= 0 else 0
    low, high = 0, max_val + 1

    while low < high:
        mid = (low + high) // 2
        # Count how many numbers in nums[left:right+1] are <= mid and >= 0
        # Since nums is sorted, find the index of the first number > mid in [left,right]
        # Using bisect_right on the slice nums[left:right+1] would be natural,
        # but we must do it on the full nums with adjusted indices.

        # Implement bisect_right manually on nums[left:right+1]
        l, r = left, right + 1
        while l < r:
            m = (l + r) // 2
            if nums[m] <= mid:
                l = m + 1
            else:
                r = m
        count = l - left  # count of numbers <= mid in nums[left:right+1]

        # Also count how many negative numbers in nums[left:right+1]
        # Since negative numbers are ignored, they do not affect missing of non-negative integers.
        # So count is number of nums in [left,right] <= mid and >=0.

        # Because nums is sorted, negative numbers are at the start.
        # So count includes negative numbers <= mid? No, because nums[m] <= mid may include negatives.
        # So we must exclude negative numbers from count:
        # Find first index of >=0 in [left,right]:
        l0, r0 = left, right
        idx0 = right + 1
        while l0 <= r0:
            m0 = (l0 + r0) // 2
            if nums[m0] >= 0:
                idx0 = m0
                r0 = m0 - 1
            else:
                l0 = m0 + 1

        # Now count numbers in [idx0, right] <= mid
        # l above is index of first number > mid in [left,right],
        # but may be before idx0 if mid < 0, which is impossible since mid >=0.
        # So if l <= idx0, count should be 0.
        if l <= idx0:
            count_nonneg = 0
        else:
            count_nonneg = l - idx0

        # If count_nonneg > mid, then all numbers from 0..mid are present
        # so missing number is > mid
        # else missing number <= mid
        if count_nonneg > mid:
            low = mid + 1
        else:
            high = mid

    return low


