from typing import List, Optional, TypeVar

T = TypeVar('T')

def find_Max(seq: List[T], low: int, high: int) -> Optional[T]:
    if low > high or low < 0 or high >= len(seq):
        return None
    if low == high:
        return seq[low]

    # If the subrange is not rotated (strictly increasing)
    if seq[low] < seq[high]:
        return seq[high]

    # Binary search for max element in rotated sorted array without duplicates
    while low < high:
        mid = (low + high) // 2
        # mid element greater than next element => mid is max
        if mid < high and seq[mid] > seq[mid + 1]:
            return seq[mid]
        # mid element smaller than previous element => mid-1 is max
        if mid > low and seq[mid] < seq[mid - 1]:
            return seq[mid - 1]
        # Decide which half to go
        if seq[mid] > seq[low]:
            # max is in right half
            low = mid + 1
        else:
            # max is in left half
            high = mid - 1

    return seq[low]


