def reverse_Array_Upto_K(arr: List[int], k: int) -> List[int]:
    # Reverse exactly the first k elements (positions 0 through k-1)
    # If k > len(arr), reverse entire list (up to len(arr))
    end = min(k, len(arr))
    return arr[:end][::-1] + arr[end:]


