def filter_data(data):
    """
    Given a dictionary mapping keys to sequences of measurements (e.g., tuples),
    return a new dictionary containing only those entries where all measurements
    are positive integers greater than zero, explicitly excluding booleans and any other numeric types.

    Parameters:
    data (dict): Dictionary where values are sequences of measurements.

    Returns:
    dict: Filtered dictionary with entries whose measurements are all positive integers > 0 (no bools).
    """
    def is_positive_int_nonbool(x):
        return type(x) is int and x > 0

    filtered = {}
    for key, measurements in data.items():
        if all(is_positive_int_nonbool(m) for m in measurements):
            filtered[key] = measurements
    return filtered


