def odd_length_sum(arr):
    n = len(arr)
    total = 0
    for i, val in enumerate(arr):
        left = i + 1
        right = n - i
        # Total number of subarrays including arr[i]:
        total_subarrays = left * right
        # Number of odd-length subarrays including arr[i]:
        odd_count = (total_subarrays + 1) // 2
        total += val * odd_count
    return total


