def check_Even_Parity(value: int) -> bool:
    # Compute minimal binary representation's '1' bits count
    # bin(value) includes a '0b' prefix and a '-' if negative
    # Count '1's only
    count_ones = bin(value).count('1')
    return (count_ones % 2) == 0


