def lucky_num(n: int) -> list[int]:
    if n <= 0:
        return []

    # Start with the odd numbers beginning at 1
    # We'll generate more than needed initially to account for removals
    # Estimate initial list length conservatively
    length = max(2 * n * n, 10)
    candidates = list(range(1, 2 * length, 2))

    idx = 1  # start from second element in candidates (index 1)
    while idx < len(candidates):
        step = candidates[idx]
        if step > len(candidates):
            break
        # Remove every step-th element starting from step-1 (0-based index)
        del candidates[step - 1::step]
        idx += 1

    return candidates[:n]


