def Find_Min_Length(lists):
    """
    Given a list of sublists, each sublist contains two integers [target, *lst],
    find the minimum length of a contiguous sublist of lst whose sum is at least target.
    Return the minimum length for each sublist, or 0 if no such sublist exists.

    Parameters:
    lists: List[List[int]]
        Each element is a list where the first element is the target sum,
        and the remaining elements form the list to search.

    Returns:
    List[int]
        List of minimum lengths corresponding to each input sublist.
    """
    results = []
    for sublist in lists:
        if len(sublist) < 2:
            # No list or target provided
            results.append(0)
            continue
        target = sublist[0]
        lst = sublist[1:]
        n = len(lst)
        min_len = n + 1
        current_sum = 0
        start = 0

        for end in range(n):
            current_sum += lst[end]
            while current_sum >= target:
                min_len = min(min_len, end - start + 1)
                current_sum -= lst[start]
                start += 1

        results.append(min_len if min_len != n + 1 else 0)
    return results


