def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle single digit numbers quickly
    if length == 1:
        return num + 1 if num < 9 else 11

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd_length = (length % 2 != 0)
    half_len = (length + 1) // 2  # length of left half including middle if odd

    left = s[:half_len]
    palindrome = make_palindrome(left, odd_length)

    if palindrome > num:
        return palindrome

    # Need to increment left half and make palindrome again
    left_num = int(left)
    left_num += 1
    left = str(left_num)

    # If incrementing left causes length overflow (e.g. 999 -> 1000)
    if len(left) > half_len:
        # For cases like 999 -> next palindrome is 1001
        # This means length increased, so palindrome is 1 followed by zeros and ending with 1
        return int("1" + ("0" * (length - 1)) + "1")

    palindrome = make_palindrome(left, odd_length)
    return palindrome


