def find_solution(a: int, b: int, n: int):
    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            # Since a*x is increasing and remainder is negative,
            # no further non-negative x will work
            return 'No solution'
        if remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1


