def get_total_number_of_sequences(m, n):
    if n == 0:
        return 0
    # dp[i][x]: number of sequences of length i ending with value x
    dp = [ [0]*(m+1) for _ in range(n+1) ]
    # Base case: sequences of length 1
    for x in range(1, m+1):
        dp[1][x] = 1

    for i in range(2, n+1):
        # prefix sums to efficiently compute sums over ranges
        prefix = [0]*(m+2)
        for x in range(1, m+1):
            prefix[x] = prefix[x-1] + dp[i-1][x]

        for x in range(1, m+1):
            left = 2*x
            if left > m:
                dp[i][x] = 0
            else:
                # sum dp[i-1][y] for y in [left, m]
                dp[i][x] = prefix[m] - prefix[left-1]

    return sum(dp[n][1:m+1])


