from typing import List

def permute_string(s: str) -> List[str]:
    def backtrack(path, counter):
        if len(path) == len(s):
            result.append("".join(path))
            return
        for ch in counter:
            if counter[ch] > 0:
                path.append(ch)
                counter[ch] -= 1
                backtrack(path, counter)
                counter[ch] += 1
                path.pop()

    result = []
    counter = {}
    for ch in s:
        counter[ch] = counter.get(ch, 0) + 1
    backtrack([], counter)
    return result


