def find_Max(arr, low, high):
    if low > high:
        return None
    if low == high:
        return arr[low]
    # If array is not rotated (sorted ascending), max is at high
    if arr[low] < arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2
        # Check if mid is pivot point (max element)
        # max element is greater than its next element
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # max element is just before mid (mid-1)
        if mid > low and arr[mid - 1] > arr[mid]:
            return arr[mid - 1]

        # Decide which side to search
        if arr[mid] >= arr[low]:
            # Left part is sorted, max must be in right part
            low = mid + 1
        else:
            # Right part is sorted, max is in left part
            high = mid - 1

    return None


