import re

def capital_words_spaces(s: str) -> str:
    # Pattern matches either:
    # - an acronym: two or more uppercase letters followed by a lowercase letter or end of string,
    # - or a capitalized word: one uppercase letter followed by lowercase letters,
    # - or any remaining uppercase letters (singletons at end)
    pattern = r'[A-Z]{2,}(?=[A-Z][a-z]|$)|[A-Z][a-z]*|[A-Z]+'
    words = re.findall(pattern, s)
    return ' '.join(words)


