def check_Even_Parity(n: int) -> bool:
    # Consider only the absolute value of n
    abs_n = abs(n)
    # Count the number of '1' bits in the binary representation of abs_n
    ones_count = bin(abs_n).count('1')
    # Return True if the count of '1' bits is even, False otherwise
    return ones_count % 2 == 0


