def substract_elements(t1, t2):
    if isinstance(t1, int) and isinstance(t2, int):
        return t1 - t2
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        # If lengths differ, treat missing elements as 0
        length = max(len(t1), len(t2))
        result = 0
        for i in range(length):
            e1 = t1[i] if i < len(t1) else 0
            e2 = t2[i] if i < len(t2) else 0
            result += substract_elements(e1, e2)
        return result
    # If one is int and other is tuple, treat int as tuple with one element
    if isinstance(t1, int) and isinstance(t2, tuple):
        return substract_elements((t1,), t2)
    if isinstance(t1, tuple) and isinstance(t2, int):
        return substract_elements(t1, (t2,))


