def lucky_num(n):
    if n <= 0:
        return []
    # Start with a list of natural numbers starting at 1
    numbers = list(range(1, n * 50))  # Start with a range large enough to get n lucky numbers
    idx = 1  # Start sieving from the second element (index 1)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element from the current list, counting from 1-based index
        # We remove elements at positions: step-1, 2*step-1, 3*step-1, ... (0-based indexing)
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx >= n:
            # Optimization: if we already have enough lucky numbers and sieving index passed n, break
            break
    return numbers[:n]


